INSERT INTO biomes (id, orderIndex, name, tagline, description, iconKey, primaryColorHex, secondaryColorHex) VALUES ('micromundo', 1, 'Micromundo', 'Un universo invisible te espera', 'Usa el microscopio virtual para descubrir células y microorganismos.', 'zone_micromundo', '#5B8C5A', '#DCEFDC');
INSERT INTO biomes (id, orderIndex, name, tagline, description, iconKey, primaryColorHex, secondaryColorHex) VALUES ('bosque_de_vida', 2, 'Bosque de Vida', 'Plantas y animales en equilibrio', 'Explora un bosque lleno de especies para observar y clasificar.', 'zone_bosque', '#2E7D32', '#E3F2E1');
INSERT INTO biomes (id, orderIndex, name, tagline, description, iconKey, primaryColorHex, secondaryColorHex) VALUES ('oceano_profundo', 3, 'Océano Profundo', 'Adaptaciones bajo el agua', 'Sumérgete para conocer criaturas marinas y sus asombrosas adaptaciones.', 'zone_oceano', '#0277BD', '#E1F5FE');
INSERT INTO biomes (id, orderIndex, name, tagline, description, iconKey, primaryColorHex, secondaryColorHex) VALUES ('cuerpo_humano', 4, 'Cuerpo Humano', 'Un laboratorio viviente', 'Construye modelos del cuerpo y descubre cómo funcionan sus sistemas.', 'zone_cuerpo', '#C62828', '#FDE8E8');
INSERT INTO biomes (id, orderIndex, name, tagline, description, iconKey, primaryColorHex, secondaryColorHex) VALUES ('ecosistemas', 5, 'Ecosistemas', 'Todo está conectado', 'Construye cadenas alimentarias y equilibra ecosistemas completos.', 'zone_ecosistemas', '#EF6C00', '#FFF3E0');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_paramecio', 'micromundo', 'Paramecio', 'Paramecium caudatum', 'MICROORGANISMO', 'Agua dulce estancada', 'Bacterias y algas microscópicas', 'HERBIVORO', 'forma de zapatilla|se mueve con cilios|unicelular', 'Puede expulsar el agua que le sobra con una estructura llamada vacuola contráctil.', 'COMUN', 'org_paramecio');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_ameba', 'micromundo', 'Ameba', 'Amoeba proteus', 'MICROORGANISMO', 'Estanques y suelos húmedos', 'Bacterias y otros microorganismos', 'HERBIVORO', 'cambia de forma constantemente|se mueve con seudópodos|unicelular', 'No tiene una forma fija: la cambia para moverse y para atrapar su alimento.', 'COMUN', 'org_ameba');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_euglena', 'micromundo', 'Euglena', 'Euglena viridis', 'MICROORGANISMO', 'Agua dulce con luz', 'Fotosíntesis y también absorbe nutrientes', 'PRODUCTOR', 'tiene un flagelo|un ojo sensible a la luz|verde por clorofila', 'Es mitad planta, mitad animal: hace fotosíntesis pero también nada activamente.', 'POCO_COMUN', 'org_euglena');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_levadura', 'micromundo', 'Levadura', 'Saccharomyces cerevisiae', 'HONGO', 'Frutas maduras y masas de pan', 'Azúcares', 'DESCOMPONEDOR', 'unicelular|se reproduce por gemación|produce burbujas de gas', 'Es la responsable de que el pan suba y de que crezca la espuma en algunas bebidas.', 'COMUN', 'org_levadura');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_tardigrado', 'micromundo', 'Tardígrado', 'Milnesium tardigradum', 'ANIMAL', 'Musgos húmedos', 'Líquidos de plantas y microorganismos', 'HERBIVORO', 'ocho patas diminutas|resiste el espacio exterior|se llama ''oso de agua''', 'Puede sobrevivir congelado, deshidratado e incluso en el vacío del espacio.', 'RARO', 'org_tardigrado');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_bacteria_intestinal', 'micromundo', 'Bacteria intestinal beneficiosa', 'Lactobacillus sp.', 'MICROORGANISMO', 'Intestino de animales', 'Restos de alimentos digeridos', 'DESCOMPONEDOR', 'ayuda a digerir alimentos|vive en grandes colonias|es beneficiosa, no todas causan enfermedades', 'Tu cuerpo convive con billones de bacterias buenas que te ayudan a digerir la comida.', 'COMUN', 'org_bacteria');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_diatomea', 'micromundo', 'Diatomea', 'Bacillariophyta', 'MICROORGANISMO', 'Océanos y lagos', 'Fotosíntesis', 'PRODUCTOR', 'caparazón de vidrio (sílice)|produce gran parte del oxígeno del planeta|forma parte del plancton', 'Las diatomeas producen alrededor de una quinta parte del oxígeno que respiramos.', 'POCO_COMUN', 'org_diatomea');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_volvox', 'micromundo', 'Volvox', 'Volvox globator', 'MICROORGANISMO', 'Estanques y charcas', 'Fotosíntesis', 'PRODUCTOR', 'forma colonias esféricas|miles de células trabajando juntas|gira al nadar', 'Aunque es diminuto, el Volvox forma colonias que giran juntas como una pequeña esfera verde.', 'RARO', 'org_volvox');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_helecho', 'bosque_de_vida', 'Helecho gigante', 'Polypodiopsida', 'PLANTA', 'Bosque húmedo', 'Fotosíntesis', 'PRODUCTOR', 'hojas grandes y divididas|se reproduce por esporas|no tiene flores', 'Los helechos existían en la Tierra mucho antes que los dinosaurios.', 'COMUN', 'org_helecho');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_roble', 'bosque_de_vida', 'Roble', 'Quercus robur', 'PLANTA', 'Bosque templado', 'Fotosíntesis', 'PRODUCTOR', 'puede vivir cientos de años|produce bellotas|raíces muy profundas', 'Un roble adulto puede alimentar a cientos de especies distintas de insectos y animales.', 'COMUN', 'org_roble');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_musgo', 'bosque_de_vida', 'Musgo', 'Bryophyta', 'PLANTA', 'Troncos y rocas húmedas', 'Fotosíntesis', 'PRODUCTOR', 'no tiene raíces verdaderas|absorbe agua por toda su superficie|forma alfombras verdes', 'El musgo ayuda a que la humedad se mantenga en el suelo del bosque.', 'COMUN', 'org_musgo');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_seta_amanita', 'bosque_de_vida', 'Seta roja', 'Amanita muscaria', 'HONGO', 'Bosques de coníferas', 'Materia orgánica en descomposición', 'DESCOMPONEDOR', 'sombrero rojo con puntos blancos|no debe tocarse ni comerse|ayuda a reciclar nutrientes', 'Los hongos no son plantas: forman su propio reino y reciclan la materia del bosque.', 'POCO_COMUN', 'org_seta');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_conejo', 'bosque_de_vida', 'Conejo silvestre', 'Oryctolagus cuniculus', 'ANIMAL', 'Praderas y bosques', 'Pasto y hierbas', 'HERBIVORO', 'orejas largas|excelente oído|se reproduce rápidamente', 'Un conejo puede girar sus orejas de forma independiente para escuchar en dos direcciones.', 'COMUN', 'org_conejo');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_ciervo', 'bosque_de_vida', 'Ciervo rojo', 'Cervus elaphus', 'ANIMAL', 'Bosques templados', 'Hojas, hierba y cortezas', 'HERBIVORO', 'astas que renueva cada año|vive en manadas|gran olfato', 'Las astas del ciervo se caen y vuelven a crecer cada año, más grandes.', 'COMUN', 'org_ciervo');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_zorro', 'bosque_de_vida', 'Zorro rojo', 'Vulpes vulpes', 'ANIMAL', 'Bosques y zonas mixtas', 'Roedores, conejos e insectos', 'CARNIVORO', 'cola espesa|muy adaptable|caza principalmente de noche', 'El zorro puede detectar el campo magnético de la Tierra para calcular sus saltos al cazar.', 'POCO_COMUN', 'org_zorro');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_buho', 'bosque_de_vida', 'Búho real', 'Bubo bubo', 'ANIMAL', 'Bosques y acantilados', 'Roedores y aves pequeñas', 'CARNIVORO', 'vuelo silencioso|gira la cabeza casi 270°|vista nocturna excelente', 'Sus plumas especiales le permiten volar sin hacer casi ningún ruido.', 'RARO', 'org_buho');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_ardilla', 'bosque_de_vida', 'Ardilla roja', 'Sciurus vulgaris', 'ANIMAL', 'Bosques de coníferas y frondosos', 'Semillas, frutos secos y hongos', 'HERBIVORO', 'cola grande y espesa|entierra reservas de comida|trepa con gran agilidad', 'Al enterrar semillas que luego olvida, la ardilla ayuda a plantar nuevos árboles.', 'COMUN', 'org_ardilla');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_escarabajo', 'bosque_de_vida', 'Escarabajo peloteros', 'Scarabaeinae', 'ANIMAL', 'Suelo del bosque', 'Estiércol y materia orgánica', 'DESCOMPONEDOR', 'forma bolas con su alimento|recicla nutrientes del suelo|muy fuerte para su tamaño', 'Puede arrastrar hasta 1.000 veces su propio peso mientras recicla el suelo del bosque.', 'POCO_COMUN', 'org_escarabajo');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_lombriz', 'bosque_de_vida', 'Lombriz de tierra', 'Lumbricus terrestris', 'ANIMAL', 'Suelo húmedo', 'Materia orgánica en descomposición', 'DESCOMPONEDOR', 'no tiene ojos ni pulmones|airea el suelo al moverse|respira por la piel', 'Las lombrices mejoran tanto el suelo que se las llama ''los ingenieros del jardín''.', 'COMUN', 'org_lombriz');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_rana_arborea', 'bosque_de_vida', 'Rana arbórea', 'Hylidae', 'ANIMAL', 'Bosque húmedo', 'Insectos', 'CARNIVORO', 'piel húmeda|salta grandes distancias|canta para comunicarse', 'Respira parcialmente a través de su piel, por eso necesita mantenerla húmeda.', 'POCO_COMUN', 'org_rana');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_mariposa', 'bosque_de_vida', 'Mariposa monarca', 'Danaus plexippus', 'ANIMAL', 'Praderas y bosques', 'Néctar de flores', 'HERBIVORO', 'migra miles de kilómetros|colores naranja y negro|se transforma desde oruga', 'Puede migrar más de 4.000 kilómetros usando el sol como brújula.', 'RARO', 'org_mariposa');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_lince', 'bosque_de_vida', 'Lince ibérico', 'Lynx pardinus', 'ANIMAL', 'Bosque mediterráneo', 'Conejos principalmente', 'CARNIVORO', 'orejas con mechones de pelo|vista y oído extraordinarios|especie protegida', 'Es uno de los felinos más amenazados del mundo, y gracias a la protección va recuperándose.', 'LEGENDARIO', 'org_lince');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_ballena_azul', 'oceano_profundo', 'Ballena azul', 'Balaenoptera musculus', 'ANIMAL', 'Océano abierto', 'Kril (pequeños crustáceos)', 'HERBIVORO', 'el animal más grande del planeta|corazón del tamaño de un auto pequeño|canta bajo el agua', 'A pesar de ser gigantesca, se alimenta de uno de los animales más pequeños del mar: el kril.', 'LEGENDARIO', 'org_ballena');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_tiburon_blanco', 'oceano_profundo', 'Tiburón blanco', 'Carcharodon carcharias', 'ANIMAL', 'Océanos templados', 'Peces, focas y otros animales marinos', 'CARNIVORO', 'detecta el olor de la sangre a gran distancia|puede percibir campos eléctricos|nada muy rápido', 'Puede detectar una sola gota de sangre diluida en un millón de gotas de agua.', 'RARO', 'org_tiburon');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_pulpo', 'oceano_profundo', 'Pulpo común', 'Octopus vulgaris', 'ANIMAL', 'Fondos rocosos', 'Cangrejos y moluscos', 'CARNIVORO', 'ocho brazos con ventosas|cambia de color y textura|extremadamente inteligente', 'Tiene tres corazones y su sangre es de color azul.', 'RARO', 'org_pulpo');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_medusa', 'oceano_profundo', 'Medusa luna', 'Aurelia aurita', 'ANIMAL', 'Aguas costeras', 'Plancton', 'HERBIVORO', 'cuerpo casi transparente|se mueve con pulsaciones|no tiene cerebro ni corazón', 'Está formada en un 95% por agua y existe desde antes que los dinosaurios.', 'POCO_COMUN', 'org_medusa');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_coral', 'oceano_profundo', 'Coral cerebro', 'Diploria labyrinthiformis', 'ANIMAL', 'Arrecifes tropicales', 'Plancton y luz solar (con algas asociadas)', 'HERBIVORO', 'forma colonias de miles de individuos|construye el esqueleto del arrecife|vive en simbiosis con algas', 'Un arrecife de coral puede albergar más especies distintas que cualquier otro ecosistema marino.', 'POCO_COMUN', 'org_coral');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_alga_marina', 'oceano_profundo', 'Alga parda gigante', 'Macrocystis pyrifera', 'PLANTA', 'Bosques submarinos', 'Fotosíntesis', 'PRODUCTOR', 'puede crecer más de 30 metros|forma auténticos bosques bajo el agua|crece muy rápido', 'Puede crecer hasta 50 centímetros en un solo día bajo condiciones ideales.', 'COMUN', 'org_alga');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_pez_payaso', 'oceano_profundo', 'Pez payaso', 'Amphiprioninae', 'ANIMAL', 'Arrecifes de coral', 'Algas y pequeños invertebrados', 'HERBIVORO', 'vive protegido entre las anémonas|es inmune a su veneno|cambia de sexo durante su vida', 'Vive en una relación de ayuda mutua con la anémona: ella lo protege y él la limpia.', 'POCO_COMUN', 'org_pez_payaso');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_estrella_mar', 'oceano_profundo', 'Estrella de mar', 'Asteroidea', 'ANIMAL', 'Fondos marinos', 'Moluscos y materia orgánica', 'CARNIVORO', 'puede regenerar brazos perdidos|no tiene cerebro|se mueve con cientos de piececillos', 'Si pierde un brazo, puede regenerarlo por completo con el paso del tiempo.', 'POCO_COMUN', 'org_estrella');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_kril', 'oceano_profundo', 'Kril antártico', 'Euphausia superba', 'ANIMAL', 'Aguas frías antárticas', 'Fitoplancton', 'HERBIVORO', 'forma enormes cardúmenes|base de la cadena alimentaria antártica|mide pocos centímetros', 'A pesar de su pequeño tamaño, alimenta a ballenas, focas y pingüinos por igual.', 'COMUN', 'org_kril');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_tortuga_marina', 'oceano_profundo', 'Tortuga marina verde', 'Chelonia mydas', 'ANIMAL', 'Océanos tropicales', 'Algas y pastos marinos', 'HERBIVORO', 'puede vivir más de 80 años|regresa a la misma playa donde nació para poner huevos|nada miles de kilómetros', 'Usa el campo magnético de la Tierra como un mapa para regresar siempre a la misma playa.', 'RARO', 'org_tortuga');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_pez_globo', 'oceano_profundo', 'Pez globo', 'Tetraodontidae', 'ANIMAL', 'Arrecifes tropicales', 'Moluscos y crustáceos', 'CARNIVORO', 'se infla al sentirse amenazado|algunas especies son venenosas|no es buen nadador', 'Se infla tragando agua para parecer demasiado grande para ser tragado por un depredador.', 'POCO_COMUN', 'org_pez_globo');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_plancton_fito', 'oceano_profundo', 'Fitoplancton', 'Varias especies', 'MICROORGANISMO', 'Superficie de todos los océanos', 'Fotosíntesis', 'PRODUCTOR', 'invisible a simple vista|base de toda la cadena marina|produce gran parte del oxígeno mundial', 'El fitoplancton produce más de la mitad del oxígeno que respiramos en todo el planeta.', 'COMUN', 'org_plancton');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_calamar_gigante', 'oceano_profundo', 'Calamar gigante', 'Architeuthis dux', 'ANIMAL', 'Aguas profundas', 'Peces y otros calamares', 'CARNIVORO', 'ojos del tamaño de un plato|puede medir más de 12 metros|vive en la oscuridad total', 'Tiene los ojos más grandes de todo el reino animal, para ver en la oscuridad de las profundidades.', 'LEGENDARIO', 'org_calamar');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_pez_linterna', 'oceano_profundo', 'Pez linterna', 'Myctophidae', 'ANIMAL', 'Aguas profundas', 'Plancton', 'HERBIVORO', 'produce su propia luz (bioluminiscencia)|vive en la zona sin luz solar|migra cada noche hacia la superficie', 'Fabrica su propia luz gracias a una reacción química en su cuerpo, como una linterna viviente.', 'RARO', 'org_pez_linterna');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_globulo_rojo', 'cuerpo_humano', 'Glóbulo rojo', 'Erythrocyte', 'MICROORGANISMO', 'Torrente sanguíneo', 'No se alimenta: transporta oxígeno', 'HERBIVORO', 'forma de disco|transporta oxígeno por el cuerpo|no tiene núcleo', 'Tu cuerpo produce alrededor de dos millones de glóbulos rojos nuevos cada segundo.', 'COMUN', 'org_globulo_rojo');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_globulo_blanco', 'cuerpo_humano', 'Glóbulo blanco', 'Leukocyte', 'MICROORGANISMO', 'Torrente sanguíneo', 'Bacterias y microbios invasores', 'CARNIVORO', 'defiende al cuerpo de infecciones|puede salir de los vasos sanguíneos|existen varios tipos', 'Son los soldados del sistema inmunitario: patrullan el cuerpo buscando invasores.', 'POCO_COMUN', 'org_globulo_blanco');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_neurona', 'cuerpo_humano', 'Neurona', 'Neuron', 'MICROORGANISMO', 'Cerebro y sistema nervioso', 'Glucosa y oxígeno', 'HERBIVORO', 'se comunica con impulsos eléctricos|tiene ramificaciones llamadas dendritas|forma redes complejísimas', 'El cerebro humano tiene unos 86.000 millones de neuronas conectadas entre sí.', 'RARO', 'org_neurona');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_bacteria_beneficiosa_intestino', 'cuerpo_humano', 'Microbiota intestinal', 'Bifidobacterium sp.', 'MICROORGANISMO', 'Intestino grueso', 'Fibra vegetal no digerida', 'DESCOMPONEDOR', 'ayuda a digerir la fibra|produce vitaminas útiles|forma parte de un ecosistema interno', 'Tu intestino alberga billones de bacterias que te ayudan a digerir y a mantenerte sano.', 'COMUN', 'org_bacteria_intestino');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_celula_muscular', 'cuerpo_humano', 'Célula muscular', 'Myocyte', 'MICROORGANISMO', 'Músculos del cuerpo', 'Glucosa y oxígeno', 'HERBIVORO', 'se contrae para generar movimiento|puede alargarse mucho|trabaja en equipo con otras fibras', 'Algunas células musculares pueden medir varios centímetros de largo, muy alargadas.', 'POCO_COMUN', 'org_celula_muscular');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_plaqueta', 'cuerpo_humano', 'Plaqueta', 'Thrombocyte', 'MICROORGANISMO', 'Torrente sanguíneo', 'No se alimenta: repara heridas', 'HERBIVORO', 'ayuda a cerrar heridas|es más pequeña que un glóbulo rojo|forma coágulos', 'Cuando te cortas, miles de plaquetas corren al lugar para taponar la herida en minutos.', 'COMUN', 'org_plaqueta');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_pasto', 'ecosistemas', 'Pasto de sabana', 'Poaceae', 'PLANTA', 'Sabana africana', 'Fotosíntesis', 'PRODUCTOR', 'crece rápido tras la lluvia|base de la cadena en la sabana|resiste el pisoteo', 'La sabana puede sostener manadas enteras de herbívoros gracias a su rápido crecimiento.', 'COMUN', 'org_pasto');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_cebra', 'ecosistemas', 'Cebra', 'Equus quagga', 'ANIMAL', 'Sabana africana', 'Pasto', 'HERBIVORO', 'rayas únicas en cada individuo|vive en manadas|gran resistencia para correr', 'El patrón de rayas de cada cebra es único, como una huella dactilar.', 'COMUN', 'org_cebra');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_leon', 'ecosistemas', 'León', 'Panthera leo', 'ANIMAL', 'Sabana africana', 'Cebras, ñus y otros herbívoros', 'CARNIVORO', 'vive en manadas llamadas orgullos|las hembras cazan en equipo|es el depredador tope de la sabana', 'Las leonas hacen la mayoría de las cacerías, a menudo trabajando en equipo.', 'POCO_COMUN', 'org_leon');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_hiena', 'ecosistemas', 'Hiena manchada', 'Crocuta crocuta', 'ANIMAL', 'Sabana africana', 'Carroña y presas pequeñas', 'DESCOMPONEDOR', 'mandíbula muy potente|vive en clanes organizados|recicla restos de otros cazadores', 'Su digestión es tan potente que puede aprovechar hasta los huesos de sus presas.', 'POCO_COMUN', 'org_hiena');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_nenufar', 'ecosistemas', 'Nenúfar', 'Nymphaea', 'PLANTA', 'Estanque de agua dulce', 'Fotosíntesis', 'PRODUCTOR', 'hojas flotantes|raíces ancladas al fondo|flores que se abren de día', 'Sus hojas flotantes son tan resistentes que pueden sostener el peso de una pequeña rana.', 'COMUN', 'org_nenufar');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_libelula', 'ecosistemas', 'Libélula', 'Anisoptera', 'ANIMAL', 'Estanque de agua dulce', 'Mosquitos y otros insectos', 'CARNIVORO', 'vuela en todas direcciones|vista compuesta con miles de lentes|pasa su juventud bajo el agua', 'Puede volar hacia adelante, atrás y de lado, como un pequeño helicóptero.', 'POCO_COMUN', 'org_libelula');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_rana_estanque', 'ecosistemas', 'Rana de estanque', 'Pelophylax', 'ANIMAL', 'Estanque de agua dulce', 'Insectos', 'CARNIVORO', 'croa para comunicarse|salta grandes distancias|vive entre el agua y la tierra', 'Empieza su vida como renacuajo respirando bajo el agua, y de adulta respira aire.', 'COMUN', 'org_rana_estanque');
INSERT INTO organisms (id, biomeId, name, scientificName, category, habitat, diet, trophicRole, characteristics, funFact, rarity, iconKey) VALUES ('org_hongo_reciclador', 'ecosistemas', 'Hongo reciclador de estanque', 'Saprolegnia sp.', 'HONGO', 'Estanque de agua dulce', 'Materia orgánica en descomposición', 'DESCOMPONEDOR', 'descompone restos de plantas y animales|libera nutrientes de vuelta al agua|invisible a simple vista en su mayoría', 'Sin descomponedores como este hongo, los nutrientes nunca volverían a estar disponibles.', 'POCO_COMUN', 'org_hongo_reciclador');
